  { p: 'What is the oldest known dated printed book?', op: ['The Gutenberg Bible', 'The Diamond Sutra of 868', 'The Shiji', 'The Tang Code'], certa: 1, exp: 'It was found at Dunhuang in 1900 and is in the British Library.' },
  { p: 'Who deposed the last Tang emperor in 907?', op: ['Huang Chao', 'Zhu Wen', 'Zhao Kuangyin', 'An Lushan'], certa: 1, exp: 'Zhu Wen founded the Later Liang, the first of the Five Dynasties.' }
